// Records, for every page in the sitemap, the date its content last really
// changed — straight out of git history — and writes it to
// src/data/sitemapLastmod.json.
//
// Why a committed JSON file instead of asking git at build time
// -------------------------------------------------------------
// The sitemap is generated by scripts/generateStaticFallbacks.mjs during
// `npm run build`, on developer machines and on CI runners alike. CI does the
// default `actions/checkout` shallow clone, whose single commit is dated "now",
// so `git log -- <path>` there would stamp all 86 URLs with today's date. That
// is exactly the synthetic timestamp Google learns to ignore. Reading a
// committed map keeps the build hermetic: the same commit always produces the
// same sitemap, on any machine.
//
// The map is refreshed by `npm run sitemap:lastmod` and verified against real
// history by `npm run sitemap:check`.
//
// Why lastmod matters here
// ------------------------
// The sitemap listed 86 URLs with no <lastmod> at all. Google treats a URL with
// no lastmod as "unknown freshness", so crawl budget is spread evenly and the
// pages that genuinely changed are not prioritised. Sending false dates is worse
// than sending none — Google discounts a lastmod it can prove is wrong, then
// ignores it site-wide. Every date below is therefore provable.
//
// Which source dates each route
// ----------------------------
//   /                        index.html, HomeSlideshow.tsx, slideExperiences.json
//   /about/                  AboutPage.tsx
//   /works/                  VideoArchive.tsx, videoArchive.json
//   /contact/                ContactWizard.tsx
//   /internship/             InternshipPage.tsx
//   /privacy-policy/         LegalPage.tsx
//   /terms-of-service/       LegalPage.tsx
//   /domains/                DomainIndex.tsx
//   /capabilities/<x>/       CapabilityDetail.tsx, capabilities.ts, leadFaqs.ts
//   /<experience>/           SliderExperience.tsx
//   /<experience>/<domain>/  the commit that last changed that domain's caption
//                            in explorerVisuals.json, plus domains.ts
//
// Shared templates deliberately do NOT date the 63 domain pages. One edit to
// DomainDetail.tsx would restamp every domain URL with the same date and destroy
// the only useful signal in the file. What Google wants is the date of a
// significant change to *that page's content*, which is what the per-caption
// pickaxe measures.
//
// Usage:
//   node scripts/generateSitemapLastmod.mjs           # refresh the JSON
//   node scripts/generateSitemapLastmod.mjs --check   # verify it against git

import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const CHECK_ONLY = process.argv.includes('--check');
const OUTPUT_FILE = path.join(root, 'src/data/sitemapLastmod.json');

/* -------------------------------------------------------------------------- */
/* Git helpers                                                                */
/* -------------------------------------------------------------------------- */

const cache = new Map();

function git(args) {
  const key = args.join('\u0000');
  if (cache.has(key)) return cache.get(key);
  let output = '';
  try {
    output = execFileSync('git', args, {
      cwd: root,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'ignore'],
    }).trim();
  } catch {
    output = '';
  }
  cache.set(key, output);
  return output;
}

/** Committer date (YYYY-MM-DD) of the last commit that touched a path. */
const lastCommitDateForPath = (file) => git(['log', '-1', '--format=%cs', '--', file]);

/**
 * Committer date of the commit that introduced or last changed a literal
 * string, so one domain page can be dated from its own content rather than
 * from the shared template that renders it.
 */
const lastCommitDateForString = (needle, file) =>
  git(['log', '-1', '--format=%cs', '-S', needle, '--', file]);

/** HEAD's committer date: the newest date the sitemap may legitimately claim. */
const headCommitDate = () => git(['log', '-1', '--format=%cs', 'HEAD']);

const newest = (dates) => dates.filter(Boolean).sort().pop() ?? '';

/* -------------------------------------------------------------------------- */
/* Route → content sources                                                    */
/* -------------------------------------------------------------------------- */

const EXPERIENCE_ROOTS = [
  '/metaverse/',
  '/mixed-reality/',
  '/virtual-reality/',
  '/augment-reality/',
  '/animation/',
  '/brand-advertisement/',
  '/media-production/',
];

const ROUTE_SOURCES = {
  '/': ['index.html', 'src/components/HomeSlideshow.tsx', 'src/data/slideExperiences.json'],
  '/about/': ['src/components/AboutPage.tsx'],
  '/works/': ['src/components/VideoArchive.tsx', 'src/data/videoArchive.json'],
  '/contact/': ['src/components/ContactWizard.tsx'],
  '/internship/': ['src/components/InternshipPage.tsx'],
  '/privacy-policy/': ['src/components/LegalPage.tsx'],
  '/terms-of-service/': ['src/components/LegalPage.tsx'],
  '/domains/': ['src/components/DomainIndex.tsx'],
};

const CAPABILITY_SOURCES = [
  'src/components/CapabilityDetail.tsx',
  'src/data/capabilities.ts',
  'src/data/leadFaqs.ts',
];

const EXPERIENCE_SOURCES = ['src/components/SliderExperience.tsx'];
const DOMAIN_SHARED_SOURCES = ['src/data/domains.ts'];
const DOMAIN_CAPTION_FILE = 'src/data/explorerVisuals.json';

/** Mirrors the slug rule in vite.config.ts, the CI route check and verifyStaticOutput. */
function slugifyDomainTitle(title) {
  return String(title || '')
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/['’]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

const explorerVisuals = JSON.parse(readFileSync(path.join(root, DOMAIN_CAPTION_FILE), 'utf8'));
const domainSharedDate = newest(DOMAIN_SHARED_SOURCES.map(lastCommitDateForPath));

/** route → date, for every domain page. */
const domainDates = new Map();
for (const [parentRoute, bundle] of Object.entries(explorerVisuals)) {
  for (const application of bundle.applications || []) {
    const route = `${parentRoute}${slugifyDomainTitle(application.caption)}/`;
    const captionDate = lastCommitDateForString(
      `"caption": ${JSON.stringify(application.caption)}`,
      DOMAIN_CAPTION_FILE,
    );
    domainDates.set(route, newest([captionDate, domainSharedDate]));
  }
}

/**
 * Lastmod for one route. Returns '' for a route shape this script does not
 * know, which the build's sitemap verifier reports instead of silently
 * publishing an undated URL.
 */
export function lastmodForRoute(route) {
  if (ROUTE_SOURCES[route]) return newest(ROUTE_SOURCES[route].map(lastCommitDateForPath));
  if (route.startsWith('/capabilities/')) return newest(CAPABILITY_SOURCES.map(lastCommitDateForPath));
  if (EXPERIENCE_ROOTS.includes(route)) return newest(EXPERIENCE_SOURCES.map(lastCommitDateForPath));
  return domainDates.get(route) ?? '';
}

/* -------------------------------------------------------------------------- */
/* Build the map                                                              */
/* -------------------------------------------------------------------------- */

const headDate = headCommitDate();
if (!headDate) {
  console.error('Cannot read git history (no commits, or not a git checkout).');
  process.exit(1);
}

// The URL list comes from the committed sitemap so the map can never drift from
// the pages the build actually publishes. Both copies must agree first.
const sitemapSource = readFileSync(path.join(root, 'public/sitemap.xml'), 'utf8');
const rootSitemap = readFileSync(path.join(root, 'sitemap.xml'), 'utf8');
if (sitemapSource !== rootSitemap) {
  console.error('public/sitemap.xml and sitemap.xml disagree. Build the site first (npm run build).');
  process.exit(1);
}
const routes = [...sitemapSource.matchAll(/<loc>https:\/\/angelcreations\.in([^<]*)<\/loc>/g)]
  .map((match) => match[1]);

const entries = {};
const unknown = [];
for (const route of routes) {
  const raw = lastmodForRoute(route);
  if (!raw) {
    unknown.push(route);
    continue;
  }
  // A future date is the one thing Google will definitely discount, so a
  // skewed clock or a bad history can never push the sitemap ahead of HEAD.
  entries[route] = raw > headDate ? headDate : raw;
}

if (unknown.length) {
  console.error(`\n${unknown.length} URL(s) have no known content source:`);
  for (const route of unknown) console.error(`  - ${route}`);
  console.error('\nAdd each route to ROUTE_SOURCES (or a resolver branch) in this script.');
  process.exit(1);
}

// Stable key order: the sitemap order, so diffs read like the sitemap.
const ordered = {};
for (const route of routes) ordered[route] = entries[route];
const serialised = `${JSON.stringify(ordered, null, 2)}\n`;

const dates = Object.values(ordered).sort();
const distinct = new Set(dates).size;
const report = [
  `routes: ${routes.length}`,
  `oldest: ${dates[0]}`,
  `newest: ${dates[dates.length - 1]}`,
  `distinct dates: ${distinct}`,
].join('\n  ');
console.log(`\n${path.relative(root, OUTPUT_FILE)}\n  ${report}\n`);

if (distinct === 1 && routes.length > 1) {
  console.error('Every route resolved to the same date, which means git history is not\nbeing read per path (a shallow clone does this). Refusing to write.');
  process.exit(1);
}

if (CHECK_ONLY) {
  const current = readFileSync(OUTPUT_FILE, 'utf8').replace(/\r\n/g, '\n');
  if (current !== serialised) {
    const drift = Object.entries(ordered).filter(([route, date]) => {
      const existing = JSON.parse(current)[route];
      return existing !== date;
    });
    console.error(`src/data/sitemapLastmod.json is stale for ${drift.length} route(s):`);
    for (const [route, date] of drift.slice(0, 20)) console.error(`  - ${route} → ${date}`);
    console.error('\nRun: npm run sitemap:lastmod && npm run build');
    process.exit(1);
  }
  console.log('src/data/sitemapLastmod.json matches git history.');
  process.exit(0);
}

writeFileSync(OUTPUT_FILE, serialised, 'utf8');
console.log('Written. Now run: npm run build   (regenerates dist, public/ and the root fallback sitemaps)');
